import { Background } from '../../backgrounds';

export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は一煎目を捨てた。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "琥珀色に少し紅のさした茶が、音もなく竹の溝へ流れていった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二煎目は濃さをならして、沈硯の杯に注いだ。彼はそれを飲んだ。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "いい茶だ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "……師匠のお茶です。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "いや。お前が淹れた茶だ。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は立ち上がり、黒鞘の剣を腰に差して、戸を押しあけた。外の男はもう待っていた。ふたりは前後になって関へ続く石段をのぼっていった。どちらも口をきかなかった。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は残りの茶を小さな急須に移し、茶籠を提げてあとを追った。", background: Background.Branch_1b_B1b_Act4_S0 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）まだ立っている人に。", background: Background.Branch_1b_B1b_Act4_S0, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一線関。両側の岩壁にはさまれて一本の道が通り、見上げれば、空は一筋の線にしか見えない。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は下の石段に立っていた。霧が足もとを流れていく。急ぐことを知らない川のように。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ふたりは七歩をへだてて立ち止まった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "兄さん、俺の剣、背負い心地はどうだい。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Smile },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "慣れない。軽すぎる。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "兄さんのは重すぎるよ。十年背負って、肩が傾いちまった。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "どちらも先には抜かなかった。日の出には、まだ少しある。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "やがて関の向こうから光があふれ、ふたりのあいだの石の上に落ちた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "剣が鞘を走る音は、一度きりだった。二振りの剣で、ひとつの音。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一手目。触れあって、すぐに離れた。湯加減をみるように。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二手目。沈硯の剣が陸遅の袖をかすめ、布を一片そぎ落とした。陸遅の剣は沈硯の喉の三寸手前で止まり、それ以上は進まなかった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）止めた。あの人、止めた。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯の眉が、かすかに動いた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "三手目、陸遅が遅れた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "はっきりと遅れた。小満の目にさえわかるほどに。剣は半ばまでしか上がらず、胸もとががら空きになった。わざと閉めずにおいた戸のように。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯の剣は、もう走りだしていた。引き戻せはしなかった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "静かだった。小満が思っていたより、ずっと。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "陸遅は一歩さがり、岩壁にもたれて、ゆっくりと座りこんだ。剣が手から滑り落ち、石の上で一度鳴った。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "お前――", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ShenYan_Pained },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "兄さんの剣は、やっぱり俺より速いな。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Hurt },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "お前は遅れた。わざとだ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "ああ。年だよ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "まだ二十七だろう。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "俺からすれば、もう年さ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は膝をつき、片手で彼の胸を押さえた。もう片方の手は、どこに置けばいいのかわからなかった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "小満。茶はあるかい。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は歩み寄り、籠から杯を取りだした。手が震えつづけて、茶が半分こぼれた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "口、への字にするなよ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は杯を受け取ったが、飲まなかった。ただ握って、湯気が指のあいだを這いのぼるにまかせた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "兄さん。帰って、湯を沸かしてくれ。師匠も年だ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "阿遅、なぜ――", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.LuChi, character: "陸遅", dialogue: "茶が冷めたよ。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.LuChi_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それきり、彼は何も言わなかった。杯はまだその手の中にあった。湯気は少しずつ細くなり、やがて消えた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "日がすっかり昇った。一筋だった空が、空いっぱいになった。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯は長いあいだ膝をついていた。それから顔を上げ、小満を見た。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.ShenYan, character: "沈硯", dialogue: "昨夜、あいつはお前に何を話した。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.ShenYan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は口を開いた。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "その言葉は喉もとまで来ていた。琥珀色に、少し紅がさして。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "……師匠のお茶は、十年たっても変わらないって。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "沈硯はうなずいた。それで十分だというように。彼は陸遅を背負い、一歩一歩、石段を下りていった。一振りの剣を腰に、もう一振りを手に握って。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "小満は冷めた一杯の茶を、関の石の上に注いだ。", background: Background.Branch_1b_B1b_Act4_S1 },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）一煎目。捨てる。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.XiaoMan_Base },
    { characterId: CharacterId.XiaoMan, character: "小満", dialogue: "（心の声）後に続くもののために、誰かが先に苦い思いをしなくちゃいけない。", background: Background.Branch_1b_B1b_Act4_S1, portrait: Portrait.XiaoMan_Base },
];
